import logging


class BaseUnit:
    def __init__(self, logger=None):
        if logger is not None and not isinstance(logger, logging.Logger):
            raise ValueError("logger must be a Logger")
        self._logger = logging.getLogger(__name__) if logger is None else logger
        self._state = "new"
        self._events = []

    @property
    def state(self):
        return self._state

    @property
    def events(self):
        return tuple(self._events)

    def _record(self, text):
        self._events.append(text)
        self._logger.debug(text)

    def initialize(self):
        if self._state != "new":
            raise RuntimeError("invalid transition")
        self._execute_initialization()
        self._state = "initialized"

    def start(self):
        if self._state != "initialized":
            raise RuntimeError("invalid transition")
        self._execute_start()
        self._state = "running"

    def stop(self):
        if self._state != "running":
            raise RuntimeError("invalid transition")
        self._execute_stop()
        self._state = "stopped"

    def _execute_initialization(self):
        self._record("base:initialization")

    def _execute_start(self):
        self._record("base:start")

    def _execute_stop(self):
        self._record("base:stop")


class AuditUnit(BaseUnit):
    def _execute_initialization(self):
        super()._execute_initialization()
        self._record("audit:initialization")

    def _execute_start(self):
        super()._execute_start()
        self._record("audit:start")

    def _execute_stop(self):
        super()._execute_stop()
        self._record("audit:stop")

    def load(self):
        return True
